const PAGE_SIZE=10;
function pageRows(rows,key){const last=Math.max(0,Math.ceil(rows.length/PAGE_SIZE)-1);S.pages[key]=Math.min(last,Math.max(0,S.pages[key]||0));return rows.slice(S.pages[key]*PAGE_SIZE,(S.pages[key]+1)*PAGE_SIZE);}
function pager(rows,key,label){pageRows(rows,key);const p=S.pages[key],start=rows.length?p*PAGE_SIZE+1:0,end=Math.min(rows.length,(p+1)*PAGE_SIZE);return '<nav class="paginator" aria-label="Paginação · '+label+'"><button data-act="page" data-list="'+key+'" data-page="'+(p-1)+'" data-key="prev-'+key+'" aria-label="Página anterior · '+label+'"'+(!p?' disabled':'')+'>← Anterior</button><span id="page-'+key+'" tabindex="-1" role="status">'+start+'–'+end+' de '+rows.length+' · '+label+'</span><button data-act="page" data-list="'+key+'" data-page="'+(p+1)+'" data-key="next-'+key+'" aria-label="Próxima página · '+label+'"'+(end>=rows.length?' disabled':'')+'>Próxima →</button></nav>';}
